def write_if_missing(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        path.write_text(content, encoding="utf-8")


def seed() -> None:
    starter_pack = ROOT / "data/taxonomy/packs/starter-pack.yaml"
    starter_pack.parent.mkdir(parents=True, exist_ok=True)
    if not starter_pack.exists():
        save_taxonomy_pack(default_taxonomy_pack(), starter_pack)

    files = {
        "data/taxonomy/source_registry.yaml": "sources: []\n",
        "data/taxonomy/synonym_map.yaml": "synonyms: {}\n",
        "data/taxonomy/candidate_backlog.yaml": "candidates: []\n",
        "data/config/model_profiles.yaml": "profiles:\n  deterministic:\n    provider: deterministic\n    model: local-keyword\n",
        "data/config/app_settings.yaml": "llm_provider: deterministic\n",
        "data/examples/demo_inputs.jsonl": DEMO_INPUTS,
        "data/benchmarks/mini_eval_set.jsonl": MINI_EVAL_SET,
        "data/review/review_store.jsonl": "",
    }
    for rel, content in files.items():
        write_if_missing(ROOT / rel, content)

    for rel in ("data/taxonomy/imports", "data/taxonomy/exports", "data/reports"):
        (ROOT / rel).mkdir(parents=True, exist_ok=True)


if __name__ == "__main__":
    seed()
    print("Demo data seeded.")
